function applyNormalize(toolResult, registry) {
  if (!registry || !registry.tools || !toolResult || toolResult.ok === false) return toolResult;
  const ref = toolResult.meta?.tool_ref || toolResult.tool_ref || toolResult.params?.tool_ref;
  if (!ref) return toolResult;
  const items = registry.tools.items || registry.tools || [];
  const toolSpec = Array.isArray(items) ? items.find((t) => t.id === ref) : null;
  if (!toolSpec || !toolSpec.normalize) return toolResult;
  const norm = toolSpec.normalize;
  let data = toolResult.data;

  // output_path extraction
  if (norm.output_path && Array.isArray(norm.output_path)) {
    for (const path of norm.output_path) {
      const parts = String(path).split('.');
      let val = data;
      for (const p of parts) {
        if (val && typeof val === 'object' && p in val) val = val[p];
        else { val = undefined; break; }
      }
      if (val !== undefined) {
        data = val;
        break;
      }
    }
  }

  // pick fields
  if (norm.pick && Array.isArray(norm.pick)) {
    const pickFields = norm.pick;
    const pickItem = (obj) => {
      if (!obj || typeof obj !== 'object') return obj;
      const res = {};
      for (const key of pickFields) {
        if (key in obj) res[key] = obj[key];
      }
      return res;
    };
    if (Array.isArray(data)) data = data.map(pickItem);
    else data = pickItem(data);
  }

  // wrap
  if (norm.wrap && data !== undefined) {
    data = { [norm.wrap]: data };
  }

  return { ...toolResult, data };
}

return items.map((item) => {
  const payload = item.json || {};
  const toolResult = payload.toolResult ||
    (payload.ok !== undefined ? payload : { ok: true, data: payload, error: null });
  const registry = payload.registry || payload.envelope?.payload?.registry || null;
  const normalized = applyNormalize(toolResult, registry);
  return { json: normalized };
});

