const step = input.step || {};
const toolRef = step.tool_ref || step.tool || step.ref || '';
const parts = String(toolRef).split('.');
const provider = (parts.shift() || '').trim();
const operation = parts.join('.').trim() || step.operation || step.action || '';
const params = step.args || step.params || {};
return [{
  json: {
    provider,
    operation,
    params,
    tool_ref: toolRef,
    step,
    envelope: input.envelope || null
  }
}];

