return items.map((item) => {
  const payload = item.json || {};
  const toolResult = payload.toolResult ||
    (payload.ok !== undefined ? payload : { ok: true, data: payload, error: null });

  const isBirthday = (event) => {
    if (!event || typeof event !== 'object') return false;
    const eventType = String(event.eventType || '').toLowerCase();
    if (eventType === 'birthday') return true;
    const summary = String(event.summary || '').toLowerCase();
    return summary.includes('birthday') || summary.includes('anniversaire');
  };

  const filterList = (list) => Array.isArray(list)
    ? list.filter((event) => !isBirthday(event))
    : list;

  const dataValue = toolResult.data;
  if (Array.isArray(dataValue)) {
    toolResult.data = filterList(dataValue);
  } else if (dataValue && typeof dataValue === 'object') {
    if (Array.isArray(dataValue.events)) {
      dataValue.events = filterList(dataValue.events);
    }
    if (Array.isArray(dataValue.items)) {
      dataValue.items = filterList(dataValue.items);
    }
  }

  return { json: toolResult };
});

